-- 00287 — Constats-types personnalisés (AUDIT).
insert into public.finding_templates (scope, control_id, classification, description, risks, recommendations)
select 'platform', c.id, 'minor_nc', t.descr, t.risks, t.recos
from (values
  ('GO.01', 'Le cadre de gouvernance SI n''est pas formalisé dans un document approuvé par la direction et diffusé aux parties prenantes.', ARRAY['Décisions SI prises sans principes ni règles communes','Absence de redevabilité de la direction sur le SI'], ARRAY['Rédiger et faire approuver un cadre de gouvernance SI (principes, instances, rôles)','Diffuser le cadre et le réviser annuellement']),
  ('GO.02', 'L''alignement entre les services SI et les besoins métier n''est pas documenté et la valeur apportée par le SI n''est pas mesurée.', ARRAY['Investissements SI peu rentables','Services SI inadaptés aux attentes métier'], ARRAY['Documenter la correspondance entre processus métier et services SI','Définir des indicateurs de valeur métier par service']),
  ('GO.03', 'Le comité de pilotage SI ne se réunit pas de façon régulière et les réunions ne font pas l''objet de procès-verbaux documentés.', ARRAY['Arbitrages SI sans traçabilité','Décisions et actions non suivies'], ARRAY['Instituer un comité de pilotage SI avec calendrier et composition formalisés','Produire et archiver des PV avec suivi des décisions']),
  ('GO.04', 'Les rôles et responsabilités en matière de SI ne sont pas formellement définis ni attribués par écrit.', ARRAY['Zones de responsabilité floues lors des incidents','Tâches critiques non assurées'], ARRAY['Formaliser une matrice RACI des activités SI','Intégrer les responsabilités SI dans les fiches de poste']),
  ('GO.05', 'L''organigramme de la DSI n''est pas formalisé ou n''est pas à jour et les périmètres de responsabilité ne sont pas précisés.', ARRAY['Chevauchements et lacunes de responsabilités','Difficulté d''escalade en cas d''incident'], ARRAY['Établir et valider l''organigramme de la DSI avec les périmètres de chaque entité','Mettre à jour l''organigramme à chaque évolution']),
  ('GO.06', 'Le budget SI n''est pas défini de manière structurée et les écarts entre prévu et réalisé ne sont pas suivis ni analysés.', ARRAY['Dépassements budgétaires non détectés','Sous-investissement sur des postes critiques'], ARRAY['Établir un budget SI annuel par nature de dépense','Mettre en place un suivi mensuel avec analyse des écarts']),
  ('GO.07', 'Aucun reporting régulier de la performance SI n''est transmis à la direction.', ARRAY['Direction non informée de l''état du SI','Problèmes de performance détectés tardivement'], ARRAY['Définir un tableau de bord SI avec indicateurs clés','Présenter ce reporting à la direction à fréquence fixe']),
  ('GO.08', 'Les compétences SI ne sont pas cartographiées et aucun plan de formation SI n''est établi.', ARRAY['Dépendance à quelques personnes clés','Obsolescence des compétences face aux évolutions techniques'], ARRAY['Cartographier les compétences SI et identifier les écarts','Établir et budgéter un plan de formation annuel']),
  ('GO.09', 'Les relations entre la DSI et les parties prenantes métier ne sont pas formalisées (pas de référents, de points de revue ni de canal de demande).', ARRAY['Besoins métier mal compris','Insatisfaction des utilisateurs'], ARRAY['Désigner des relais métier et organiser des revues périodiques','Formaliser le processus de recueil des besoins']),
  ('GO.10', 'Les exigences de qualité SI ne sont pas définies et aucun processus de suivi de la qualité n''est en place.', ARRAY['Qualité de service hétérogène','Absence d''amélioration mesurable'], ARRAY['Définir des objectifs et indicateurs qualité pour les services SI','Mettre en place un suivi qualité avec revue périodique']),
  ('GO.11', 'Les exigences légales, réglementaires et contractuelles applicables au SI ne sont pas identifiées dans un registre ni suivies.', ARRAY['Sanctions réglementaires','Manquements contractuels non détectés'], ARRAY['Constituer un registre des exigences applicables avec responsables','Planifier une veille et une revue de conformité périodiques']),
  ('GO.12', 'Aucun programme d''audit interne SI formalisé n''existe et les constats ne alimentent pas un processus d''amélioration continue.', ARRAY['Faiblesses du SI non détectées','Actions correctives non suivies'], ARRAY['Établir un programme annuel d''audit interne SI','Suivre les écarts dans un plan d''actions avec revue de direction']),
  ('GR.01', 'Le niveau de risque IT acceptable n''est pas défini ni validé par la direction.', ARRAY['Décisions de traitement sans critère d''acceptation','Risques acceptés implicitement'], ARRAY['Définir une déclaration d''appétence au risque IT','Faire valider les seuils par la direction']),
  ('GR.02', 'Aucune méthodologie d''analyse de risques SI n''est documentée ni appliquée de façon homogène.', ARRAY['Évaluations non comparables','Risques majeurs omis'], ARRAY['Adopter une méthode (ISO 27005, EBIOS RM) et la documenter','Former les analystes et l''appliquer à tous les périmètres']),
  ('GR.03', 'La cartographie des risques SI n''est pas à jour et les risques ne sont pas évalués régulièrement.', ARRAY['Risques émergents non pris en compte','Priorisation basée sur des données périmées'], ARRAY['Constituer et mettre à jour un registre des risques SI','Planifier une mise à jour au moins annuelle']),
  ('GR.04', 'Les risques identifiés ne font pas tous l''objet d''un plan de traitement documenté avec responsable et échéance.', ARRAY['Risques sans mesure de réduction','Actions non suivies'], ARRAY['Définir un plan de traitement par risque (réduire, accepter, transférer, éviter)','Affecter responsables et échéances et suivre l''avancement']),
  ('GR.05', 'Aucune veille structurée sur les menaces et vulnérabilités n''est organisée et les informations ne sont pas analysées.', ARRAY['Vulnérabilités exploitables non corrigées','Réaction tardive aux nouvelles menaces'], ARRAY['S''abonner à des sources fiables (CERT, éditeurs) et désigner un responsable','Analyser et tracer l''impact des alertes sur le SI']),
  ('GR.06', 'Les risques SI ne sont pas revus périodiquement et les plans de traitement ne sont pas mis à jour.', ARRAY['Registre obsolète','Mesures de traitement inadaptées'], ARRAY['Planifier une revue au moins annuelle des risques','Mettre à jour les plans de traitement après chaque revue']),
  ('GR.07', 'Les risques SI ne sont pas intégrés au dispositif global de gestion des risques de l''organisation.', ARRAY['Vision fragmentée des risques','Risques SI sous-estimés par la direction'], ARRAY['Remonter les risques SI majeurs dans la cartographie globale','Aligner les échelles d''évaluation avec la gestion des risques groupe']),
  ('AE.01', 'Aucun schéma directeur SI formalisé et à jour n''est aligné sur la stratégie métier.', ARRAY['Évolutions SI non coordonnées','Dette technique croissante'], ARRAY['Élaborer un schéma directeur SI triennal aligné sur la stratégie','Réviser annuellement et le faire valider par la direction']),
  ('AE.02', 'Les couches métier, applicative, technique et données de l''architecture d''entreprise ne sont pas documentées.', ARRAY['Impacts des changements mal évalués','Perte de connaissance'], ARRAY['Documenter les quatre couches d''architecture','Désigner un responsable architecture']),
  ('AE.03', 'L''inventaire des applications et de leurs interdépendances n''est pas maintenu à jour.', ARRAY['Pannes en cascade non anticipées','Applications obsolètes non identifiées'], ARRAY['Établir une cartographie applicative avec flux et dépendances','Intégrer sa mise à jour au processus de changement']),
  ('AE.04', 'Les schémas réseau, les zones de sécurité et l''infrastructure ne sont pas documentés ou pas à jour.', ARRAY['Segmentation non maîtrisée','Délai de diagnostic allongé lors d''incidents'], ARRAY['Documenter les schémas réseau et zones de sécurité','Mettre à jour la documentation à chaque changement d''infrastructure']),
  ('AE.05', 'Les principes de sécurité by design et de défense en profondeur ne sont pas formalisés ni appliqués aux nouveaux projets.', ARRAY['Vulnérabilités introduites dès la conception','Coûts de correction élevés'], ARRAY['Définir des principes d''architecture sécurisée','Intégrer une revue sécurité dans les phases de conception']),
  ('AE.06', 'Aucun processus de veille technologique n''est en place pour identifier les opportunités d''innovation.', ARRAY['Retard technologique','Opportunités d''optimisation manquées'], ARRAY['Désigner un responsable de veille technologique','Présenter une synthèse de veille semestrielle au comité SI']),
  ('AE.07', 'Aucun plan de transformation digitale n''est défini ni suivi.', ARRAY['Initiatives digitales dispersées','Perte de compétitivité'], ARRAY['Définir un plan de transformation digitale avec objectifs et jalons','Suivre son avancement en comité de pilotage']),
  ('AE.08', 'Le portefeuille de projets et services n''est pas géré avec des critères de priorisation formalisés.', ARRAY['Ressources allouées à des projets peu prioritaires','Surcharge des équipes'], ARRAY['Constituer un portefeuille projets unique avec critères de priorisation','Arbitrer le portefeuille périodiquement en comité']),
  ('GD.01', 'Aucune politique de gestion des données n''est formalisée et approuvée.', ARRAY['Traitement hétérogène des données','Responsabilités non définies sur les données'], ARRAY['Rédiger et faire approuver une politique de gestion des données','Désigner des propriétaires de données']),
  ('GD.02', 'Les informations ne sont pas classifiées selon leur niveau de sensibilité.', ARRAY['Protection inadaptée des données sensibles','Fuites de données'], ARRAY['Définir une grille de classification et les règles de traitement','Classifier les informations des processus critiques']),
  ('GD.03', 'L''inventaire des actifs matériels, logiciels et de données n''est pas complet ni maintenu à jour.', ARRAY['Actifs non protégés ni patchés','Écarts entre parc réel et parc déclaré'], ARRAY['Constituer un inventaire exhaustif avec propriétaire par actif','Automatiser la découverte et le rapprocher régulièrement']),
  ('GD.04', 'Le registre des traitements de données personnelles prévu à l''article 30 du RGPD n''est pas tenu ou est incomplet.', ARRAY['Sanctions de l''autorité de protection des données','Impossibilité de démontrer la conformité'], ARRAY['Établir un registre complet des traitements','Désigner un responsable de sa mise à jour']),
  ('GD.05', 'Aucune analyse d''impact sur la vie privée n''est réalisée pour les traitements à risque.', ARRAY['Risques sur les droits des personnes non évalués','Sanctions réglementaires'], ARRAY['Identifier les traitements nécessitant une AIPD','Définir une méthode d''AIPD et la réaliser pour ces traitements']),
  ('GD.06', 'Aucun processus formalisé ne permet aux personnes concernées d''exercer leurs droits (accès, rectification, suppression) dans les délais.', ARRAY['Réclamations et plaintes','Sanctions pour non-respect des délais'], ARRAY['Mettre en place une procédure et un point de contact pour l''exercice des droits','Tracer les demandes et les délais de réponse']),
  ('GD.07', 'Les durées de conservation ne sont pas définies et aucun processus de suppression sécurisée n''est appliqué.', ARRAY['Conservation excessive de données','Fuites lors de la mise au rebut de supports'], ARRAY['Définir un référentiel de durées de conservation par catégorie','Mettre en œuvre des procédures de suppression et destruction sécurisées']),
  ('GD.08', 'Les transferts de données ne sont pas encadrés par des mesures de sécurité et des garanties réglementaires documentées.', ARRAY['Interception ou fuite de données','Transferts illicites hors du territoire'], ARRAY['Recenser les transferts internes et externes','Chiffrer les échanges et contractualiser les garanties']),
  ('GD.09', 'Les enregistrements réglementaires ne sont pas protégés de façon suffisante contre la perte et l''altération.', ARRAY['Perte de preuves exigées par la réglementation','Altération non détectée'], ARRAY['Identifier les enregistrements réglementaires et leurs exigences','Mettre en place sauvegarde, contrôle d''intégrité et droits d''accès restreints']),
  ('GD.10', 'La conformité des licences logicielles n''est pas suivie et la propriété intellectuelle n''est pas protégée par des mesures formalisées.', ARRAY['Redressements et pénalités éditeurs','Usage de logiciels non autorisés'], ARRAY['Inventorier les licences et les rapprocher des installations','Désigner un responsable de la gestion des licences']),
  ('GS.01', 'Aucun catalogue de services SI formalisé et accessible aux utilisateurs n''est publié.', ARRAY['Attentes métier floues','Demandes mal orientées'], ARRAY['Établir un catalogue des services avec description et responsables','Le publier sur un portail accessible']),
  ('GS.02', 'Aucun accord de niveau de service n''est défini ni suivi pour les services critiques.', ARRAY['Qualité de service non mesurable','Litiges avec les métiers et fournisseurs'], ARRAY['Définir des SLA pour les services critiques','Mesurer et rapporter les niveaux de service mensuellement']),
  ('GS.03', 'Aucun point de contact unique n''est en place pour les demandes et incidents des utilisateurs.', ARRAY['Incidents perdus ou traités tardivement','Absence de traçabilité'], ARRAY['Mettre en place un service desk avec outil de ticketing','Définir les processus de prise en charge et d''escalade']),
  ('GS.04', 'Les procédures d''exploitation clés (démarrage/arrêt, supervision, sauvegarde, exploitation courante) ne sont pas toutes documentées ni mises à jour, et reposent sur le savoir informel des exploitants.', ARRAY['Dépendance aux personnes clés et perte de savoir-faire en cas d''absence ou de départ','Erreurs d''exploitation et temps de résolution allongé','Pratiques hétérogènes entre exploitants'], ARRAY['Inventorier et rédiger les procédures d''exploitation des services critiques','Instaurer une revue périodique et un versionnage des procédures','Rendre les procédures accessibles aux équipes d''exploitation dans un référentiel centralisé']),
  ('GS.05', 'Le processus de gestion des incidents n''est pas formalisé de bout en bout : catégorisation, priorisation, escalade et clôture des incidents ne sont pas systématiquement tracées.', ARRAY['Rétablissement tardif des services et impact accru sur les métiers','Incidents non tracés ou perdus, sans possibilité de mesure','Absence d''escalade adaptée des incidents majeurs'], ARRAY['Formaliser un processus d''incidents avec grille de priorité et délais de prise en charge','Utiliser un outil de ticketing pour tracer tous les incidents','Définir une procédure d''escalade et suivre des indicateurs de résolution']),
  ('GS.06', 'Les causes racines des incidents récurrents ne sont pas systématiquement analysées, et les incidents répétitifs sont traités par des contournements sans traitement définitif.', ARRAY['Récurrence des mêmes incidents et surcharge des équipes','Coût de support élevé et dégradation de la qualité de service','Solutions de contournement non documentées'], ARRAY['Instaurer un processus de gestion des problèmes avec analyse de causes racines','Alimenter une base d''erreurs connues et suivre les actions correctives','Revoir périodiquement les incidents récurrents pour ouvrir des problèmes']),
  ('GS.07', 'Les changements IT ne suivent pas un processus uniforme : certaines modifications sont réalisées sans demande formelle, analyse d''impact, plan de retour arrière ni approbation tracée.', ARRAY['Interruptions de service causées par des changements non maîtrisés','Introduction de vulnérabilités ou de régressions','Impossibilité de retracer l''origine d''une modification'], ARRAY['Formaliser un processus de changement (demande, évaluation d''impact, approbation, retour arrière)','Classer les changements par type (standard, normal, urgent) avec circuits adaptés','Tracer tous les changements dans un outil et en mesurer le taux d''échec']),
  ('GS.08', 'Il n''existe pas de comité d''approbation des changements (CAB) constitué, avec composition, fréquence de réunion et critères de saisine définis pour les changements significatifs.', ARRAY['Déploiement de changements majeurs sans validation transverse','Conflits de planification entre changements','Responsabilité de la décision non établie'], ARRAY['Constituer un CAB avec représentants IT, sécurité et métiers','Définir les critères de saisine, la fréquence des réunions et un CAB d''urgence','Consigner les décisions et comptes rendus du comité']),
  ('GS.09', 'Les mises en production ne sont pas systématiquement planifiées, testées et tracées : les recettes, fenêtres de déploiement et plans de retour arrière ne sont pas formalisés.', ARRAY['Régressions et indisponibilités lors des déploiements','Déploiements non tracés et non reproductibles','Impossibilité de revenir rapidement à la version précédente'], ARRAY['Établir un calendrier de mises en production avec fenêtres de déploiement','Exiger une recette validée et un plan de retour arrière avant chaque déploiement','Tracer chaque mise en production (version, date, responsable, résultat)']),
  ('GS.10', 'Les actifs IT ne sont pas gérés sur l''ensemble de leur cycle de vie : l''inventaire est incomplet ou obsolète et les étapes d''acquisition, d''affectation et de retrait ne sont pas suivies.', ARRAY['Actifs non référencés échappant aux mesures de sécurité','Matériels et logiciels obsolètes ou sans support maintenus en service','Coûts de licences et de maintenance mal maîtrisés'], ARRAY['Constituer un inventaire exhaustif des actifs avec propriétaire et statut','Définir et suivre le cycle de vie (acquisition, exploitation, fin de vie)','Réconcilier périodiquement l''inventaire avec le parc réel']),
  ('GS.11', 'Il n''existe pas de CMDB à jour décrivant les ressources clés et leurs relations ; les dépendances entre applications, serveurs et services ne sont pas cartographiées.', ARRAY['Analyse d''impact des changements et incidents peu fiable','Allongement des délais de diagnostic','Dépendances critiques méconnues'], ARRAY['Mettre en place une CMDB couvrant les éléments de configuration critiques et leurs relations','Alimenter la CMDB par découverte automatisée lorsque possible','Définir un responsable et un contrôle périodique de l''exactitude des données']),
  ('GS.12', 'La politique de sauvegarde n''est pas formalisée : fréquence, durée de rétention et périmètre des données et systèmes sauvegardés ne sont pas définis ni validés avec les métiers.', ARRAY['Données critiques non sauvegardées','Rétention inadaptée aux exigences légales et métiers','Perte de données supérieure à l''acceptable'], ARRAY['Rédiger une politique de sauvegarde alignée sur les RPO et exigences légales','Cartographier le périmètre sauvegardé et corriger les écarts','Prévoir des copies externalisées et protégées contre la suppression']),
  ('GS.13', 'Les procédures de restauration ne sont pas testées régulièrement ; il n''existe pas de preuve récente de restauration réussie des données et systèmes sauvegardés.', ARRAY['Sauvegardes inexploitables découvertes lors d''un sinistre','Durée de restauration supérieure aux objectifs de reprise','Procédures de restauration obsolètes'], ARRAY['Planifier des tests de restauration périodiques par échantillonnage des systèmes critiques','Documenter les résultats et les délais de restauration obtenus','Corriger les anomalies détectées et mettre à jour les procédures']),
  ('GS.14', 'Les niveaux de disponibilité convenus ne sont pas définis ni mesurés : il n''y a ni SLA formalisé avec les métiers ni suivi du taux de disponibilité des services.', ARRAY['Attentes métiers non alignées avec la qualité de service réelle','Indisponibilités non détectées ou non analysées','Absence de base pour prioriser les investissements'], ARRAY['Définir des niveaux de service de disponibilité avec les métiers','Mettre en place une supervision mesurant la disponibilité réelle','Produire un reporting périodique des écarts et plans d''amélioration']),
  ('GS.15', 'Les ressources (stockage, calcul, réseau) ne font pas l''objet d''une surveillance de capacité ni d''une planification, et le dimensionnement futur n''est pas anticipé.', ARRAY['Saturation des ressources et dégradation des performances','Achats d''urgence coûteux','Indisponibilités liées à un manque de capacité'], ARRAY['Superviser l''utilisation des ressources avec seuils d''alerte','Établir un plan de capacité annuel basé sur les tendances et projets','Revoir le dimensionnement avant chaque évolution majeure']),
  ('GS.16', 'Les systèmes critiques ne disposent pas tous de mécanismes de redondance : des points uniques de défaillance subsistent (serveurs, liens réseau, alimentation, stockage).', ARRAY['Interruption de service lors de la panne d''un seul composant','Temps d''arrêt prolongé pour réparation','Impact majeur sur les processus critiques'], ARRAY['Identifier les points uniques de défaillance des systèmes critiques','Mettre en œuvre redondance et bascule automatique pour les composants clés','Tester périodiquement les mécanismes de bascule']),
  ('GS.17', 'Le plan de continuité d''activité IT est incomplet : les services critiques, les objectifs RTO/RPO et les rôles de gestion de crise ne sont pas tous formalisés ni approuvés.', ARRAY['Réponse désorganisée lors d''un sinistre','Délais de reprise non maîtrisés','Obligations de continuité non couvertes'], ARRAY['Compléter le PCA à partir d''une analyse d''impact sur l''activité (BIA)','Définir RTO/RPO, rôles et chaîne de décision de crise','Faire approuver le PCA par la direction et le diffuser']),
  ('GS.18', 'Les procédures de reprise des systèmes critiques sont partiellement documentées : l''ordre de redémarrage, les dépendances et les ressources nécessaires ne sont pas détaillés pour tous les systèmes.', ARRAY['Reprise lente ou erronée après un sinistre','Dépendance aux personnes connaissant les systèmes','Objectifs de reprise non atteints'], ARRAY['Documenter pour chaque système critique les procédures de reprise pas à pas','Préciser dépendances, ordre de redémarrage et sites de repli','Mettre à jour le PRA après tout changement majeur']),
  ('GS.19', 'Les plans de continuité et de reprise ne sont pas testés régulièrement : les exercices sont ponctuels, partiels ou sans compte rendu formalisé.', ARRAY['Plans inefficaces non détectés avant un sinistre réel','Équipes non entraînées à leurs rôles','Objectifs RTO/RPO non vérifiés'], ARRAY['Établir un programme annuel de tests PCA/PRA (table-top puis bascule technique)','Documenter les résultats et suivre les actions correctives','Impliquer les métiers dans les exercices']),
  ('GS.20', 'Aucune méthodologie de gestion de projets SI n''est appliquée systématiquement : cadrage, planification, suivi des risques et clôture varient selon les projets.', ARRAY['Dépassements de délais et de budgets','Livrables non alignés avec les besoins métiers','Risques projet non identifiés'], ARRAY['Adopter une méthodologie de projet standard avec jalons et livrables types','Mettre en place un comité de pilotage et un suivi du portefeuille de projets','Réaliser un bilan de clôture pour chaque projet']),
  ('GS.21', 'La sécurité n''est pas intégrée à toutes les phases du cycle de développement : exigences de sécurité, revues de code, tests de sécurité et gestion des vulnérabilités ne sont pas systématiques.', ARRAY['Vulnérabilités applicatives livrées en production','Coût de correction accru en phase tardive','Exposition aux attaques sur les applications'], ARRAY['Définir des exigences et standards de codage sécurisé','Intégrer revues de code et tests de sécurité (SAST/DAST) dans le pipeline','Former les développeurs aux risques applicatifs courants']),
  ('GS.22', 'Les environnements de développement, test et production ne sont pas isolés : des accès, comptes ou données de production sont partagés avec les environnements de développement ou de test.', ARRAY['Modification accidentelle de la production','Exposition de données réelles en environnement de test','Propagation d''erreurs de développement en production'], ARRAY['Séparer logiquement et physiquement les environnements dev/test/prod','Interdire l''usage de données de production non anonymisées en test','Distinguer les comptes et droits par environnement']),
  ('MS.01', 'La politique de sécurité SI existe mais n''est pas à jour, ou n''est pas formellement approuvée par la direction ni communiquée à l''ensemble du personnel et des tiers concernés.', ARRAY['Règles de sécurité ignorées ou appliquées de façon hétérogène','Absence d''engagement de la direction','Difficulté à sanctionner les manquements'], ARRAY['Mettre à jour la politique et la faire approuver par la direction','Diffuser la politique et recueillir l''accusé de lecture','Prévoir une revue annuelle ou après évolution majeure']),
  ('MS.02', 'L''organisation de la sécurité est partiellement définie : le RSSI n''est pas formellement nommé ou ses rôles, responsabilités et son rattachement ne sont pas clarifiés.', ARRAY['Responsabilités de sécurité diffuses','Absence de pilotage et d''arbitrage des risques','Faible prise en compte de la sécurité dans les projets'], ARRAY['Nommer officiellement un RSSI avec lettre de mission','Définir l''organisation sécurité, les rôles et les instances de pilotage','Rattacher le RSSI à un niveau garantissant son indépendance']),
  ('MS.03', 'Le processus de gestion des incidents de sécurité est incomplet : la détection, la qualification, l''escalade et le retour d''expérience ne sont pas formalisés pour tous les types d''incidents.', ARRAY['Détection tardive des incidents de sécurité','Réponse inadaptée et aggravation de l''impact','Absence de capitalisation sur les incidents'], ARRAY['Formaliser les procédures de détection, qualification et escalade des incidents de sécurité','Désigner une cellule de réponse aux incidents avec astreinte','Réaliser un retour d''expérience après chaque incident majeur']),
  ('MS.04', 'Les procédures de notification des violations de données aux autorités et aux personnes concernées ne sont pas complètement formalisées : délais, contenus et responsables de la notification ne sont pas tous définis.', ARRAY['Notification tardive ou incomplète aux autorités','Sanctions réglementaires','Atteinte à la confiance des personnes concernées'], ARRAY['Formaliser une procédure de notification avec délais réglementaires (72 h)','Désigner les responsables et préparer des modèles de notifications','Tenir un registre des violations de données']),
  ('MS.05', 'Les exigences de sécurité ne sont pas systématiquement imposées aux fournisseurs et sous-traitants : les contrats ne comportent pas tous de clauses de sécurité, de confidentialité et d''audit.', ARRAY['Fuite de données chez un prestataire','Niveau de sécurité des tiers non maîtrisé','Absence de recours contractuel en cas d''incident'], ARRAY['Définir des exigences de sécurité standard à intégrer aux contrats','Évaluer la conformité des fournisseurs critiques avant et pendant la relation','Prévoir un droit d''audit et des clauses de notification d''incident']),
  ('MS.06', 'Les risques de la chaîne d''approvisionnement numérique (logiciels, composants, services tiers) ne sont ni identifiés ni gérés ; les dépendances externes ne sont pas cartographiées.', ARRAY['Compromission via un composant ou logiciel tiers vulnérable','Dépendance critique à un fournisseur unique','Absence de visibilité sur les composants utilisés'], ARRAY['Cartographier les dépendances logicielles et services tiers critiques','Intégrer l''évaluation des risques supply chain dans les achats et le développement','Surveiller les vulnérabilités des composants externes']),
  ('MS.07', 'Les services cloud utilisés ne sont pas tous évalués et suivis sur le plan de la sécurité : inventaire incomplet, absence de revue des garanties, de la localisation des données et de la répartition des responsabilités.', ARRAY['Données hébergées sans garanties suffisantes','Usage de services cloud non autorisés (shadow IT)','Mauvaises configurations exposant des données'], ARRAY['Inventorier les services cloud utilisés et leur criticité','Évaluer chaque service (certifications, localisation, chiffrement, réversibilité)','Superviser la configuration et les accès aux environnements cloud']),
  ('MS.08', 'Les antécédents des candidats ne sont pas systématiquement vérifiés avant l''embauche, notamment pour les postes sensibles ou à accès privilégiés.', ARRAY['Recrutement de personnes présentant un risque d''intégrité','Accès à des données sensibles par du personnel non vérifié','Responsabilité de l''organisation engagée'], ARRAY['Définir une procédure de vérification proportionnée à la sensibilité du poste','Vérifier identité, diplômes et références avant embauche','Conserver la preuve des vérifications dans le respect de la réglementation']),
  ('MS.09', 'Il n''existe pas de programme de sensibilisation et de formation à la sécurité suivi : les actions sont ponctuelles et sans mesure de participation ni d''efficacité.', ARRAY['Succès des attaques d''ingénierie sociale et d''hameçonnage','Erreurs humaines à l''origine d''incidents','Politique de sécurité mal comprise'], ARRAY['Établir un programme annuel de sensibilisation pour tout le personnel','Prévoir des formations ciblées pour profils sensibles (administrateurs, développeurs)','Suivre la participation et mesurer l''efficacité (simulations d''hameçonnage)']),
  ('MS.10', 'Le processus de départ et de mutation n''est pas appliqué de façon fiable : certains accès ne sont pas révoqués dans les délais et la restitution des actifs n''est pas systématiquement vérifiée.', ARRAY['Accès résiduels exploitables par d''anciens collaborateurs','Perte d''équipements et de données','Cumul de droits lors des mutations'], ARRAY['Formaliser un processus RH/IT de départ et de mutation avec checklist','Révoquer les accès le jour du départ et revoir les droits à chaque mutation','Contrôler périodiquement les comptes de personnes ayant quitté l''organisation']),
  ('MS.11', 'Les accords de confidentialité ne sont pas signés par tous les collaborateurs et prestataires ayant accès à des informations sensibles.', ARRAY['Divulgation d''informations confidentielles sans recours juridique','Fuite de données par des prestataires','Preuve insuffisante des engagements de confidentialité'], ARRAY['Faire signer un NDA à tout collaborateur et prestataire à l''entrée en relation','Régulariser les accords manquants pour le personnel et les tiers existants','Tenir un registre des accords signés avec leur échéance']),
  ('MS.12', 'Les règles de sécurité du télétravail ne sont pas définies ou appliquées : usage de postes non maîtrisés, absence de VPN obligatoire et de règles sur les réseaux personnels.', ARRAY['Fuite de données depuis des postes ou réseaux non sécurisés','Compromission du SI via des accès distants','Perte ou vol d''équipements hors des locaux'], ARRAY['Rédiger une politique de télétravail incluant exigences techniques et comportementales','Imposer VPN, chiffrement du poste et MFA pour l''accès à distance','Sensibiliser les télétravailleurs aux risques spécifiques']),
  ('MS.13', 'Les accès physiques aux locaux et aux zones sensibles (salle serveurs, locaux techniques) ne sont pas suffisamment contrôlés : absence de journalisation, de gestion des visiteurs ou de revue des droits d''accès.', ARRAY['Accès non autorisé aux équipements critiques','Vol ou sabotage de matériel','Absence de traçabilité des entrées'], ARRAY['Mettre en place un contrôle d''accès avec journalisation pour les zones sensibles','Gérer et accompagner les visiteurs avec registre','Revoir périodiquement les droits d''accès physiques']),
  ('MS.14', 'Les dispositifs de protection environnementale (détection et extinction incendie, onduleurs, climatisation) sont absents, insuffisants ou non maintenus pour les zones hébergeant les équipements critiques.', ARRAY['Destruction de matériel par incendie, surchauffe ou coupure électrique','Interruption prolongée des services','Perte de données'], ARRAY['Équiper les locaux techniques de détection et d''extinction incendie adaptées','Prévoir onduleurs, groupe électrogène et climatisation redondée','Planifier la maintenance et les tests périodiques des dispositifs']),
  ('MS.15', 'Les données ne sont pas effacées de manière sécurisée avant la mise au rebut du matériel : il n''existe ni procédure d''effacement ni preuve de destruction des supports.', ARRAY['Fuite de données résiduelles sur du matériel cédé ou jeté','Non-conformité en matière de protection des données','Récupération de données par des tiers'], ARRAY['Définir une procédure d''effacement sécurisé ou de destruction des supports','Exiger un certificat de destruction ou d''effacement','Tenir un registre des matériels mis au rebut']),
  ('MS.16', 'Les règles de gestion des accès logiques sont formalisées de façon incomplète ou ne sont pas appliquées : revues périodiques des droits absentes, droits attribués sans validation formelle.', ARRAY['Accumulation de droits excessifs','Accès non autorisés aux données et applications','Absence de séparation des tâches'], ARRAY['Formaliser une politique de contrôle d''accès fondée sur le moindre privilège','Instaurer un processus d''attribution validé par les propriétaires de ressources','Effectuer des revues périodiques des droits d''accès']),
  ('MS.17', 'Les comptes à privilèges ne sont pas tous inventoriés ni surveillés : des comptes administrateurs génériques ou dormants subsistent et leurs actions ne sont pas journalisées.', ARRAY['Compromission d''un compte administrateur avec impact étendu','Actions privilégiées non traçables','Comptes dormants exploitables'], ARRAY['Inventorier et justifier tous les comptes à privilèges','Interdire les comptes partagés et journaliser les actions privilégiées','Revoir périodiquement les comptes administrateurs et supprimer les comptes inutiles']),
  ('MS.18', 'L''authentification multi-facteurs n''est pas déployée sur l''ensemble des systèmes critiques : certains accès administrateurs, distants ou aux applications sensibles reposent uniquement sur un mot de passe.', ARRAY['Compromission de comptes par vol ou devinette de mots de passe','Accès non autorisé aux systèmes critiques','Contournement facilité par hameçonnage'], ARRAY['Étendre le MFA aux accès distants, administrateurs et applications critiques','Prioriser le déploiement selon la criticité des systèmes','Imposer des facteurs robustes (application d''authentification, clé physique)']),
  ('MS.19', 'Les données sensibles ne sont pas systématiquement chiffrées en transit et au repos : certains flux, bases de données, postes ou supports de sauvegarde ne sont pas protégés par chiffrement.', ARRAY['Interception ou lecture de données en clair','Fuite de données en cas de perte ou vol de supports','Non-conformité aux exigences de protection des données'], ARRAY['Identifier les données sensibles et définir une politique de chiffrement','Chiffrer les flux (TLS) et les stockages contenant des données sensibles','Mettre en place une gestion sécurisée des clés cryptographiques']),
  ('MS.20', 'Le réseau n''est pas suffisamment segmenté et filtré : les règles de pare-feu ne sont pas revues, des flux inutiles restent ouverts et la surveillance réseau est partielle.', ARRAY['Propagation latérale d''une attaque dans le réseau','Exposition de services inutilement ouverts','Détection tardive d''activités anormales'], ARRAY['Segmenter le réseau par zones de sensibilité avec filtrage entre zones','Revoir périodiquement les règles de pare-feu et supprimer les flux inutiles','Déployer une surveillance réseau avec alertes'])
) as t(code, descr, risks, recos)
join public.controls c on c.code = t.code and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000014')
where not exists (select 1 from public.finding_templates ft where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'minor_nc');

insert into public.finding_templates (scope, control_id, classification, description, risks, recommendations)
select 'platform', c.id, 'major_nc', t.descr, t.risks, t.recos
from (values
  ('GO.01', 'Aucun cadre de gouvernance SI n''existe : les décisions SI reposent sur des pratiques informelles sans validation de la direction générale.', ARRAY['Pilotage du SI non maîtrisé et non aligné sur la stratégie','Responsabilité de la direction non établie en cas d''incident majeur','Dérive des coûts et des risques SI'], ARRAY['Établir un cadre de gouvernance SI aligné sur COBIT EDM01 et le faire valider par la direction','Désigner un sponsor exécutif et définir les instances de décision','Mettre en place une revue annuelle du cadre']),
  ('GO.03', 'Aucun comité de pilotage SI n''est en place : les arbitrages SI ne font l''objet d''aucune instance ni d''aucune traçabilité.', ARRAY['Absence de supervision de la direction sur le SI','Priorités SI contradictoires et non arbitrées','Impossibilité de démontrer la gouvernance en cas d''audit'], ARRAY['Créer un comité de pilotage SI trimestriel présidé par la direction','Formaliser une charte du comité et les PV types','Suivre les décisions dans un registre d''actions']),
  ('GO.11', 'Aucune identification ni suivi des exigences légales et réglementaires applicables au SI n''est réalisé, exposant l''organisation à des non-conformités non connues.', ARRAY['Sanctions administratives et financières','Atteinte à la réputation','Responsabilité engagée des dirigeants'], ARRAY['Réaliser un recensement des textes applicables (protection des données, cybersécurité, sectoriels)','Désigner un responsable conformité et tenir un registre','Auditer annuellement la conformité']),
  ('GR.01', 'La direction n''a défini aucune appétence au risque IT, aucun seuil d''acceptation n''existe pour arbitrer les risques SI.', ARRAY['Acceptation de risques excessifs sans validation','Incohérence des décisions de traitement','Exposition financière non maîtrisée'], ARRAY['Formaliser l''appétence et les seuils de tolérance au risque IT','Faire approuver par la direction et communiquer','Réviser annuellement']),
  ('GR.02', 'Il n''existe pas de méthodologie d''analyse de risques SI : les risques ne sont ni identifiés ni évalués selon un processus reproductible.', ARRAY['Absence de vision des risques réels','Investissements de sécurité mal ciblés','Non-conformité aux référentiels'], ARRAY['Définir et documenter une méthodologie d''analyse de risques','Réaliser une première analyse sur les actifs critiques','Intégrer la méthode au processus de projet']),
  ('GR.03', 'Aucune cartographie des risques SI n''est tenue : les risques ne sont ni identifiés, ni évalués, ni hiérarchisés.', ARRAY['Menaces critiques non connues','Incidents majeurs non anticipés','Impossibilité de prioriser les budgets de sécurité'], ARRAY['Établir une cartographie complète des risques SI','Évaluer probabilité et impact par risque','Présenter la cartographie à la direction']),
  ('GR.04', 'Aucun plan de traitement des risques SI n''est défini : les risques identifiés restent sans mesure ni responsable.', ARRAY['Matérialisation de risques connus','Absence de réduction de l''exposition','Défaut de diligence en cas d''incident'], ARRAY['Élaborer un plan de traitement priorisé pour les risques élevés','Faire valider les risques résiduels par la direction','Suivre les actions en comité']),
  ('GR.05', 'Aucune veille sur les menaces et vulnérabilités n''est assurée, les alertes de sécurité ne sont ni collectées ni analysées.', ARRAY['Exploitation de vulnérabilités connues','Compromission du SI','Correctifs critiques appliqués tardivement'], ARRAY['Mettre en place un processus de veille et de gestion des vulnérabilités','Corréler les alertes avec l''inventaire des actifs','Définir des délais de correction par criticité']),
  ('AE.05', 'Aucun principe de sécurité by design n''est appliqué : les projets sont conçus sans exigence de sécurité ni défense en profondeur.', ARRAY['Compromission facilitée du SI','Failles structurelles coûteuses à corriger','Non-respect des bonnes pratiques de sécurité'], ARRAY['Établir des principes d''architecture sécurisée obligatoires','Imposer une validation sécurité avant mise en production','Former les architectes et chefs de projet']),
  ('GD.02', 'Aucune classification des informations n''existe : les données sensibles ne sont pas identifiées ni protégées en conséquence.', ARRAY['Divulgation de données confidentielles','Mesures de sécurité mal dimensionnées','Non-conformité réglementaire'], ARRAY['Établir un schéma de classification et sensibiliser les utilisateurs','Appliquer des mesures de protection par niveau','Marquer les documents et systèmes sensibles']),
  ('GD.03', 'Il n''existe aucun inventaire fiable des actifs informationnels, empêchant toute protection ciblée.', ARRAY['Actifs critiques non sécurisés','Analyse de risques incomplète','Shadow IT non maîtrisé'], ARRAY['Réaliser un inventaire initial des actifs critiques','Mettre en place un outil de gestion de configuration','Définir un propriétaire et une revue périodique']),
  ('GD.04', 'Aucun registre des traitements de données personnelles n''est tenu, en violation de l''article 30 du RGPD.', ARRAY['Sanctions financières','Atteinte à la confiance des personnes concernées','Traitements illicites non détectés'], ARRAY['Recenser tous les traitements et constituer le registre','Désigner un DPO ou référent','Réviser le registre à chaque nouveau traitement']),
  ('GS.05', 'Aucun processus de gestion des incidents opérationnel n''existe : les incidents sont traités au cas par cas, sans enregistrement, priorisation ni escalade, y compris pour les services critiques.', ARRAY['Interruptions prolongées des services critiques','Impossibilité de démontrer la maîtrise des incidents aux régulateurs ou clients','Récurrence des incidents faute de capitalisation'], ARRAY['Mettre en place un processus d''incidents et un outil de ticketing couvrant tout le périmètre','Définir des SLA de traitement par niveau de priorité et une chaîne d''escalade','Produire un reporting mensuel des incidents présenté à la direction']),
  ('GS.07', 'Aucun processus de gestion des changements contrôlé n''est appliqué : des modifications des systèmes de production sont effectuées sans demande, évaluation de risque ni approbation préalable.', ARRAY['Pannes en production liées à des changements non évalués','Modifications non autorisées ou malveillantes non détectées','Perte de maîtrise de la configuration des systèmes'], ARRAY['Mettre en œuvre un processus de changement obligatoire pour tout système en production','Restreindre les droits de modification en production aux seuls changements approuvés','Auditer régulièrement la conformité des changements aux demandes enregistrées']),
  ('GS.12', 'Aucune politique de sauvegarde n''est définie : les données et systèmes critiques ne sont pas sauvegardés selon une fréquence, une rétention et un périmètre déterminés.', ARRAY['Perte définitive de données en cas de panne, erreur ou ransomware','Impossibilité de restaurer les services critiques','Non-respect des obligations légales de conservation'], ARRAY['Définir et approuver une politique de sauvegarde couvrant tous les systèmes critiques','Mettre en œuvre des sauvegardes automatisées avec copie hors site ou immuable','Superviser les sauvegardes et traiter les échecs sous délai défini']),
  ('GS.13', 'Aucun test de restauration n''a été réalisé : la capacité à restaurer les données et systèmes critiques à partir des sauvegardes n''est pas démontrée.', ARRAY['Perte de données irrécupérable en cas d''incident','Arrêt prolongé des activités critiques','Fausse assurance liée à des sauvegardes non vérifiées'], ARRAY['Réaliser sans délai un test de restauration complet sur les systèmes critiques','Instaurer un calendrier annuel de tests avec rapport formalisé','Mesurer les délais réels et les comparer aux RTO/RPO attendus']),
  ('GS.17', 'Aucun plan de continuité d''activité IT formalisé n''existe pour assurer la continuité des services critiques en cas de sinistre.', ARRAY['Arrêt prolongé des activités essentielles lors d''un sinistre majeur','Pertes financières et atteinte à la réputation','Non-conformité aux exigences réglementaires et contractuelles'], ARRAY['Réaliser une analyse d''impact sur l''activité pour identifier les services critiques','Élaborer et faire approuver un PCA avec RTO/RPO et gouvernance de crise','Désigner un responsable de la continuité et planifier la maintenance du plan']),
  ('GS.18', 'Aucun plan de reprise d''activité IT n''est documenté : il n''existe pas de procédure de reprise des systèmes critiques ni de site de secours défini.', ARRAY['Impossibilité de rétablir les services critiques après un sinistre','Perte de données et arrêt d''activité de longue durée','Défaillance face aux exigences des régulateurs et clients'], ARRAY['Élaborer un PRA couvrant l''ensemble des systèmes critiques avec site de secours','Documenter les procédures de reprise et les responsabilités associées','Valider le PRA par un premier exercice de bascule']),
  ('GS.19', 'Aucun test du PCA/PRA n''a été réalisé : l''efficacité des plans de continuité et de reprise n''est pas démontrée.', ARRAY['Échec de la reprise lors d''un sinistre réel','Arrêt prolongé des services critiques','Plans obsolètes et inapplicables'], ARRAY['Planifier et exécuter un premier test complet du PCA/PRA dans les six mois','Formaliser un rapport d''exercice avec écarts et plan d''actions','Répéter les tests au moins annuellement']),
  ('GS.21', 'Aucun cycle de développement sécurisé n''est défini : les applications sont développées sans exigences de sécurité ni tests de sécurité avant mise en production.', ARRAY['Exploitation de failles applicatives par des attaquants','Fuite ou altération de données sensibles','Non-conformité aux exigences de sécurité réglementaires'], ARRAY['Établir un SDLC sécurisé avec points de contrôle sécurité obligatoires à chaque phase','Réaliser des tests de sécurité avant toute mise en production','Gérer et corriger les vulnérabilités selon un délai défini par criticité']),
  ('MS.01', 'Aucune politique de sécurité de l''information n''est formalisée et approuvée par la direction ; le cadre de gouvernance de la sécurité n''est pas établi.', ARRAY['Absence de cadre de référence pour les mesures de sécurité','Non-conformité aux exigences réglementaires et normatives','Exposition accrue aux incidents faute de directives'], ARRAY['Rédiger une politique de sécurité SI alignée sur ISO 27001 et la faire approuver par la direction','Communiquer la politique à tous les collaborateurs et prestataires','Décliner la politique en procédures et standards opérationnels']),
  ('MS.02', 'Aucune organisation de la sécurité de l''information n''est définie et aucun RSSI n''est nommé ; les responsabilités de sécurité ne sont pas attribuées.', ARRAY['Absence de pilotage de la sécurité et de réponse coordonnée aux incidents','Mesures de sécurité non appliquées faute de responsable','Défaut de redevabilité face à la direction et aux autorités'], ARRAY['Nommer un RSSI avec mandat, moyens et rattachement à la direction','Établir un comité de sécurité périodique','Formaliser la matrice des rôles et responsabilités de sécurité']),
  ('MS.03', 'Aucun processus de détection, d''escalade et de réponse aux incidents de sécurité n''est en place ; les incidents ne sont ni qualifiés ni tracés.', ARRAY['Compromission prolongée des systèmes sans détection','Fuite de données et pertes financières','Incapacité à contenir et analyser une attaque'], ARRAY['Mettre en place un plan de réponse aux incidents de sécurité avec rôles et procédures','Déployer des capacités de détection et de journalisation centralisée','Tester le plan par des exercices de simulation']),
  ('MS.04', 'Aucune procédure de notification des violations de données personnelles aux autorités et aux personnes concernées n''est formalisée.', ARRAY['Non-respect des délais légaux de notification et sanctions associées','Préjudice pour les personnes concernées faute d''information','Atteinte grave à la réputation'], ARRAY['Établir et approuver une procédure de notification conforme à la réglementation applicable','Intégrer la notification au processus de gestion des incidents de sécurité','Former les équipes concernées et tester la procédure']),
  ('MS.05', 'Aucune exigence de sécurité n''est imposée aux fournisseurs et sous-traitants ayant accès aux systèmes ou aux données de l''organisation.', ARRAY['Compromission via un prestataire non maîtrisé','Divulgation de données sensibles sans recours contractuel','Non-conformité réglementaire sur la sous-traitance'], ARRAY['Inventorier les fournisseurs ayant accès aux données ou systèmes et les classer par criticité','Intégrer des clauses de sécurité obligatoires dans tous les contrats','Mettre en place un suivi périodique de la conformité des fournisseurs critiques']),
  ('MS.07', 'Aucune évaluation de sécurité ni suivi n''est réalisé sur les services cloud utilisés pour traiter des données de l''organisation.', ARRAY['Fuite ou perte de données hébergées chez des tiers','Non-conformité réglementaire sur la localisation et la protection des données','Absence de réversibilité en cas de défaillance du fournisseur'], ARRAY['Établir une politique d''usage du cloud avec processus d''approbation préalable','Réaliser une évaluation de sécurité des services cloud existants','Définir clauses de réversibilité et suivi périodique de la sécurité']),
  ('MS.09', 'Aucun programme de sensibilisation et de formation à la sécurité n''est en place ; le personnel n''est pas formé aux risques et règles de sécurité.', ARRAY['Forte exposition à l''hameçonnage et à l''ingénierie sociale','Incidents d''origine humaine fréquents','Règles de sécurité ignorées par les collaborateurs'], ARRAY['Lancer un programme de sensibilisation obligatoire pour tous les collaborateurs','Intégrer une formation sécurité à l''accueil des nouveaux arrivants','Suivre des indicateurs de participation et de comportement']),
  ('MS.13', 'Aucun contrôle d''accès physique n''est mis en œuvre pour les zones sensibles : la salle serveurs est accessible sans restriction ni traçabilité.', ARRAY['Intrusion, vol ou sabotage des équipements critiques','Accès direct aux données par une personne non autorisée','Interruption de service d''origine malveillante'], ARRAY['Sécuriser la salle serveurs par un contrôle d''accès nominatif et journalisé','Restreindre l''accès aux seules personnes autorisées','Installer une vidéosurveillance et des alarmes sur les zones sensibles']),
  ('MS.16', 'Aucune politique de contrôle d''accès n''est formalisée ni appliquée : les droits sont attribués sans validation ni revue, sans respect du moindre privilège.', ARRAY['Accès non autorisé à des données sensibles','Fraude ou erreurs liées à l''absence de séparation des tâches','Impossibilité de justifier les accès lors d''un audit ou d''un incident'], ARRAY['Rédiger et appliquer une politique de contrôle d''accès avec gestion formelle des droits','Mettre en place des revues semestrielles des habilitations','Appliquer le principe de moindre privilège et de séparation des tâches']),
  ('MS.17', 'Les comptes administrateurs ne sont ni inventoriés ni restreints ni surveillés : des droits d''administration étendus sont attribués sans contrôle ni traçabilité.', ARRAY['Prise de contrôle totale du SI en cas de compromission d''un compte','Abus de privilèges non détectés','Altération ou suppression de données critiques'], ARRAY['Établir l''inventaire complet des comptes à privilèges et réduire leur nombre','Mettre en place une gestion des accès privilégiés (coffre-fort, comptes nominatifs, MFA)','Surveiller et auditer régulièrement les actions des administrateurs']),
  ('MS.18', 'Aucune authentification multi-facteurs n''est déployée : l''accès aux systèmes critiques, y compris administrateurs et distants, repose uniquement sur des mots de passe.', ARRAY['Prise de contrôle de comptes par attaque sur mots de passe ou hameçonnage','Intrusion dans les systèmes critiques et exfiltration de données','Rançongiciel facilité par la compromission de comptes'], ARRAY['Déployer le MFA en priorité sur les accès administrateurs, distants et messagerie','Étendre progressivement le MFA à tous les systèmes critiques','Compléter par une politique de mots de passe robuste']),
  ('MS.19', 'Aucun chiffrement des données sensibles n''est mis en œuvre, ni en transit ni au repos ; les données circulent et sont stockées en clair.', ARRAY['Divulgation massive de données en cas d''interception ou de vol','Non-conformité aux obligations de protection des données personnelles','Perte de confiance des clients et sanctions'], ARRAY['Chiffrer en priorité les données sensibles au repos (bases, postes, sauvegardes)','Imposer le chiffrement des flux par TLS sur tous les services','Définir une politique de cryptographie et de gestion des clés']),
  ('MS.20', 'Le réseau est à plat, sans segmentation ni filtrage effectif, et sans surveillance active des flux ; les systèmes critiques sont accessibles depuis l''ensemble du réseau.', ARRAY['Compromission généralisée du SI à partir d''un seul poste','Exfiltration de données non détectée','Exposition directe des systèmes critiques aux attaques'], ARRAY['Mettre en place une segmentation isolant les systèmes critiques et les zones exposées','Déployer pare-feu et règles de filtrage selon le principe du moindre accès','Activer une supervision et détection d''intrusion sur le réseau'])
) as t(code, descr, risks, recos)
join public.controls c on c.code = t.code and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000014')
where not exists (select 1 from public.finding_templates ft where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'major_nc');
